// Parse faceted search parameters
const query = $json.query || $json.body?.query || '';
const facetFields = $json.facet_fields || $json.body?.facet_fields || ['document_type', 'department'];
const limit = $json.limit || $json.body?.limit || 10;
const minScore = $json.min_score || $json.body?.min_score || 0.7;

if (!query) {
  throw new Error('query is required');
}

if (!Array.isArray(facetFields)) {
  throw new Error('facet_fields must be an array');
}

return {
  json: {
    query,
    facet_fields: facetFields,
    limit,
    min_score: minScore
  }
};

// Format faceted search results with facet breakdown
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message || 'Faceted search error',
      results: [],
      facets: {}
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name || result.document_name,
  document_type: result.metadata?.document_type || 'unknown',
  department: result.metadata?.department || 'unknown',

  // Content
  content: result.text || result.content,
  content_preview: (result.text || result.content || '').substring(0, 200) + '...',

  // Scores
  relevance_score: result.score || 0,
  quality_score: result.metadata?.quality_score || 0,

  // Document properties
  document_type_category: result.metadata?.document_type_category || 'unknown',
  is_process: result.metadata?.is_process || false,
  is_form: result.metadata?.is_form || false,
  is_template: result.metadata?.is_template || false,

  // Railway-specific
  fleet_type: result.metadata?.fleet_type || null,
  train_id: result.metadata?.train_id || null,
  standard_compliance: result.metadata?.standard_compliance || null,

  document_url: result.metadata?.document_url || null
}));

// Extract facets
const facets = response.facets || {};

// Sort facets by count
const sortedFacets = {};
for (const [field, counts] of Object.entries(facets)) {
  sortedFacets[field] = Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .reduce((obj, [key, value]) => ({ ...obj, [key]: value }), {});
}

return {
  json: {
    success: true,
    results,
    facets: sortedFacets,
    metadata: {
      query: response.metadata?.query || '',
      total_results: results.length,
      facet_fields: response.metadata?.facet_fields || [],
      search_type: 'faceted',
      min_score_applied: response.metadata?.min_score || 0.7
    }
  }
};
